#include "LibraryManager.h"
#include <algorithm>
#include <chrono>
#include <iomanip>
#include <sstream>
#include <ctime>
#include <stdexcept>

namespace library {
namespace {
long daysRecursive(long n){if(n<=0)return 0;if(n==1)return 1;long h=n/2;return daysRecursive(h)*2+n%2;}
std::string trim(std::string s){auto first=s.find_first_not_of(" \t\r\n");if(first==std::string::npos)return {};auto last=s.find_last_not_of(" \t\r\n");return s.substr(first,last-first+1);}
}
std::string LibraryManager::today(){auto now=std::chrono::system_clock::now();auto t=std::chrono::system_clock::to_time_t(now);std::tm tm{};localtime_s(&tm,&t);std::ostringstream s;s<<std::put_time(&tm,"%Y-%m-%d");return s.str();}
std::string LibraryManager::dateAfter(int offset){std::tm tm{};std::istringstream(today())>>std::get_time(&tm,"%Y-%m-%d");tm.tm_mday+=offset;std::mktime(&tm);std::ostringstream s;s<<std::put_time(&tm,"%Y-%m-%d");return s.str();}
LibraryItem& LibraryManager::requiredItem(const std::string& id) const {auto* i=db_.findItem(id);if(!i)throw std::invalid_argument("Item ID not found.");return *i;}
std::shared_ptr<LibraryItem> LibraryManager::addItem(ItemType type,const std::string& title,const std::string& author,int year){int maxYear=std::stoi(today().substr(0,4))+1;auto cleanTitle=trim(title),cleanAuthor=trim(author);if(cleanTitle.empty()||cleanAuthor.empty()||year<1000||year>maxYear)throw std::invalid_argument("Enter a title, author, and valid publication year.");auto id=IDGenerator::nextItemId();std::shared_ptr<LibraryItem> i;switch(type){case ItemType::Book:i=std::make_shared<Book>(id,cleanTitle,cleanAuthor,year);break;case ItemType::Magazine:i=std::make_shared<Magazine>(id,cleanTitle,cleanAuthor,year);break;case ItemType::Journal:i=std::make_shared<Journal>(id,cleanTitle,cleanAuthor,year);break;}db_.addItem(i);undo_.push({true,i,0});return i;}
void LibraryManager::deleteItem(const std::string& id){auto key=trim(id);auto& item=requiredItem(key);if(!item.isAvailable())throw std::invalid_argument("Return the item before deleting it.");auto count=db_.accessCount(key);auto saved=db_.removeItem(key);undo_.push({false,saved,count});}
bool LibraryManager::undo(){if(undo_.empty())return false;auto a=undo_.top();undo_.pop();if(a.wasAdd)db_.removeItem(a.item->id());else{db_.addItem(a.item);db_.restoreAccessCount(a.item->id(),a.accessCount);}return true;}
std::shared_ptr<LibraryItem> LibraryManager::borrow(const std::string& id,const std::string& userId){auto& item=requiredItem(trim(id));auto uid=trim(userId);if(!item.isAvailable())throw std::invalid_argument("Item is already borrowed; reserve it instead.");auto& user=db_.getOrCreateUser(uid);int active=0;for(auto& i:db_.items())if(i->borrowerId()==uid)++active;if(active>=MaxActiveLoans)throw std::invalid_argument("Borrower has reached the active loan limit.");item.checkOut(uid,dateAfter(LoanDays));user.history.push_back({item.id(),item.title(),today(),""});db_.recordAccess(&item);return item.clone();}
std::string LibraryManager::returnItem(const std::string& id,const std::string& userId){auto key=trim(id),uid=trim(userId);auto& item=requiredItem(key);if(item.isAvailable())throw std::invalid_argument("Item is not currently borrowed.");if(item.borrowerId()!=uid)throw std::invalid_argument("Borrower ID does not match this loan.");auto it=db_.users().find(uid);if(it!=db_.users().end())for(auto r=it->second.history.rbegin();r!=it->second.history.rend();++r)if(r->itemId==key&&r->returnedOn.empty()){r->returnedOn=today();break;}item.checkIn();for(auto r=db_.reservations().begin();r!=db_.reservations().end();)if(r->itemId==key){auto next=*r;r=db_.reservations().erase(r);int active=0;for(auto& held:db_.items())if(held->borrowerId()==next.userId)++active;if(active>=MaxActiveLoans)continue;item.checkOut(next.userId,dateAfter(LoanDays));db_.getOrCreateUser(next.userId).history.push_back({item.id(),item.title(),today(),""});return "Returned and issued to next reservation: "+next.userId;}else ++r;return "Item returned successfully.";}
void LibraryManager::reserve(const std::string& id,const std::string& userId){auto key=trim(id),uid=trim(userId);auto& item=requiredItem(key);if(item.isAvailable())throw std::invalid_argument("Item is available; borrow it directly.");if(uid.empty()||uid==item.borrowerId())throw std::invalid_argument("Enter another borrower ID.");for(auto& r:db_.reservations())if(r.itemId==key&&r.userId==uid)throw std::invalid_argument("This user already has a reservation.");db_.getOrCreateUser(uid);db_.reservations().push_back({key,uid,today()});}
long LibraryManager::overdueCharge(const LibraryItem& item) const {if(item.isAvailable()||item.dueDate()>=today())return 0;std::tm due{};std::istringstream(item.dueDate())>>std::get_time(&due,"%Y-%m-%d");std::tm now{};std::istringstream(today())>>std::get_time(&now,"%Y-%m-%d");auto a=std::chrono::system_clock::from_time_t(std::mktime(&due)),b=std::chrono::system_clock::from_time_t(std::mktime(&now));long days=static_cast<long>(std::chrono::duration_cast<std::chrono::hours>(b-a).count()/24);return daysRecursive(days)*ChargePerDay;}
std::vector<std::shared_ptr<LibraryItem>> LibraryManager::mostBorrowed() const{auto a=db_.items();std::stable_sort(a.begin(),a.end(),[](auto&x,auto&y){return x->borrowCount()>y->borrowCount();});if(a.size()>10)a.resize(10);return a;}
std::vector<std::string> LibraryManager::overdueUsers() const{std::vector<std::string> out;for(auto&[id,u]:db_.users()){(void)u;for(auto&i:db_.items())if(i->borrowerId()==id&&overdueCharge(*i)>0){out.push_back(id);break;}}return out;}
std::unordered_map<std::string,size_t> LibraryManager::categoryDistribution() const{std::unordered_map<std::string,size_t> out;for(auto&i:db_.items())++out[toString(i->type())];return out;}
}
